draw.fragment:
precision highp float;
varying vec2 vUv;
uniform sampler2D uImage;
uniform int uOperation;
uniform float uScale;
uniform float uOpacity;
uniform vec2 uBlurStep;
uniform bool uFinal;
vec4 sampleImage(vec2 point) {
    if (any(lessThan(point,vec2(0.0))) || any(greaterThan(point,vec2(1.0)))) return vec4(0.0);
    return texture2D(uImage,point);
}
void main() {
    vec2 point=(vUv-0.5)/uScale+0.5;
    vec4 value=sampleImage(point);
    if (uOperation == 1) {
        value*=0.227027;
        value+=sampleImage(point+uBlurStep*1.384615)*0.316216;
        value+=sampleImage(point-uBlurStep*1.384615)*0.316216;
        value+=sampleImage(point+uBlurStep*3.230769)*0.070270;
        value+=sampleImage(point-uBlurStep*3.230769)*0.070270;
    }
    value*=uOpacity;
    if (uFinal) value=vec4(value.rgb+vec3(2.0,4.0,3.0)/255.0*(1.0-value.a),1.0);
    gl_FragColor=value;
}

algorithms.source:
export function create() {
    return {
        prepareFrame(frame) {
            const n = (id, fallback = 0) =>
                typeof frame.parameters[id]?.value === 'number' ? frame.parameters[id].value : fallback;
            const pass = changes => ({
                program: 'draw',
                uniforms: {
                    uImage: 'source',
                    uOperation: 0,
                    uScale: 1,
                    uOpacity: 1,
                    uBlurStep: [0, 0],
                    uFinal: false,
                    ...changes,
                },
            });
            const range = frame.range;
            let progress = range
                ? Math.max(0, Math.min(1, (frame.time - range.startSeconds) / (range.endSeconds - range.startSeconds)))
                : 0;
            if (frame.parameters.smooth?.value === true) progress = progress * progress * (3 - 2 * progress);
            return { passes: [pass({ uOpacity: n('from') + (n('to', 1) - n('from')) * progress })] };
        },
    };
}
